    connect(interfaces,&QPushButton::clicked,this,&TunDialog::showInterfaces); connect(apply_,&QPushButton::clicked,this,[this] { const auto options=draft(); if (!validTunOptions(options)) return; waiting_=true; applyingOptions_=true; updateActions(); controller_->updateTunSettings(options,tunOptionsJson(initial_)); }); connect(c,&AppController::stateChanged,this,&TunDialog::updateActions);
    connect(c,&AppController::operationFinished,this,[this](bool ok,const QString& text) { if (!waiting_) return; waiting_=false; const bool applied=applyingOptions_,cleaned=cleaning_; applyingOptions_=cleaning_=false; hint_->setText(ok?"操作完成；TUN "+(controller_->state().tunObserved?QString("运行中"):QString("未运行")):text); if (ok&&applied) { initial_=controller_->settings(); enabled_->setChecked(initial_.tunEnabled); stack_->setCurrentIndex(stack_->findData(initial_.tunStack)); strict_->setChecked(initial_.tunStrictRoute); mtu_->setValue(initial_.tunMtu); dnsHijack_->setChecked(initial_.tunDnsHijack); routes_->setPlainText(initial_.tunExcludeRoutes.join('\n')); } else if (ok&&cleaned) { initial_.tunEnabled=controller_->settings().tunEnabled; enabled_->setChecked(initial_.tunEnabled); } inspect(); });
