Settings TunDialog::draft() const { auto value=initial_; value.tunEnabled=enabled_->isChecked(); value.tunStack=stack_->currentData().toString(); value.tunStrictRoute=strict_->isChecked(); value.tunMtu=mtu_->value(); value.tunDnsHijack=dnsHijack_->isChecked(); value.tunExcludeRoutes.clear(); for (const auto& route:normalizeTunRoutes(routes_->toPlainText()).data.value("routes").toArray()) value.tunExcludeRoutes.append(route.toString()); return value; }
void TunDialog::inspect() {
    if (loading_) return; loading_=true; updateActions(); const QPointer<TunDialog> guard(this);
    controller_->inspectTunService([guard](Result result) { if (!guard) return; guard->loading_=false; guard->known_=result.ok; guard->service_=result.data; guard->installed_=result.data.value("installed").toBool(); guard->status_->setText(!result.ok?result.error:!guard->installed_?QString("服务未安装 · 点击“安装服务”后即可启用"):result.data.value("running").toBool()?QString("权限服务已启动"):QString("服务已安装 · 按需启动"));
        const auto data=result.data; const auto session=data.value("session").toObject(); QStringList lines{"服务版本："+data.value("version").toString("未知"),"服务内核："+(!data.contains("core_matches")?QString("未知"):data.value("core_matches").toBool()?QString("与随包版本匹配"):QString("不匹配，需要修复")),"所选内核："+(!data.contains("client_core_matches")?QString("未检查"):data.value("client_core_matches").toBool()?QString("随包版本匹配"):QString("不匹配，请在设置恢复随包 mihomo")),"高级选项："+(data.value("advanced_options").toBool()?QString("支持"):QString("旧版或未安装，修复后支持")),"会话："+(session.value("active").toBool()?QString("活动"):session.value("cleanup_pending").toBool()?QString("清理待确认"):QString("未活动")),"恢复标记："+(data.value("recovery_marker").toBool()?QString("存在（运行中正常，停止后须确认清理）"):QString("无"))}; if (session.value("active").toBool()) lines<<"接口："+(session.value("adapter_up").toBool()?QString("已启动"):QString("未确认"))<<"自动路由："+(session.value("routes").toBool()?QString("已观察"):QString("未确认"))<<"DNS接口："+(session.value("dns_configured").toBool()?QString("已配置"):QString("未确认")); if (session.contains("mtu")) lines<<"接口 MTU："+QString::number(session.value("mtu").toInt()); guard->details_->setPlainText(lines.join('\n')); guard->updateActions(); });
}
void TunDialog::updateActions() {
    const auto& state=controller_->state(); const bool idle=!state.busy&&!state.exiting&&!state.readOnly&&!waiting_; const bool removable=!controller_->settings().tunEnabled&&!state.tunObserved&&state.core!=CoreState::Failed;
    install_->setEnabled(idle&&!loading_&&known_&&!installed_&&removable); repair_->setEnabled(idle&&!loading_&&known_&&installed_&&removable); remove_->setEnabled(idle&&!loading_&&known_&&installed_&&removable); refresh_->setEnabled(!loading_&&!waiting_);
    const bool pending=service_.value("session").toObject().value("cleanup_pending").toBool()||(service_.value("recovery_marker").toBool()&&!service_.value("session").toObject().value("active").toBool()); cleanup_->setEnabled(idle&&known_&&installed_&&!state.ready&&(pending||state.core==CoreState::Failed));
    const auto checked=normalizeTunRoutes(routes_->toPlainText()); const auto options=draft(); const bool stale=tunOptionsJson(initial_)!=tunOptionsJson(controller_->settings()); const bool changed=tunOptionsJson(options)!=tunOptionsJson(initial_); validation_->setText(!checked.ok?checked.error:stale?QString("设置已在其他窗口改变，请重新打开；此处草稿保持不变"):enabled_->isChecked()&&known_&&installed_&&!service_.value("client_core_matches").toBool()?QString("启用需要随包锁定版本，请先在设置恢复随包内核"):QString());
    apply_->setEnabled(idle&&!stale&&checked.ok&&changed&&(!options.tunEnabled||(known_&&installed_&&service_.value("client_core_matches").toBool()))); enabled_->setEnabled(idle&&(installed_||initial_.tunEnabled)); for (auto* widget:QList<QWidget*>{stack_,strict_,mtu_,dnsHijack_,routes_}) widget->setEnabled(idle);
}
void TunDialog::showInterfaces() {
    auto* dialog=new QDialog(this); dialog->setAttribute(Qt::WA_DeleteOnClose); dialog->setObjectName("networkInterfacesDialog"); dialog->setWindowTitle("网络接口（只读）"); dialog->resize(660,410); auto* layout=new QVBoxLayout(dialog); auto* info=new QLabel("正在读取本机接口…"); info->setWordWrap(true); info->setTextFormat(Qt::PlainText); layout->addWidget(info); auto* table=new QTableWidget(0,3); table->setHorizontalHeaderLabels({"接口","状态","本机地址"}); table->setEditTriggers(QAbstractItemView::NoEditTriggers); table->setShowGrid(false); table->verticalHeader()->hide(); table->horizontalHeader()->setSectionResizeMode(2,QHeaderView::Stretch); layout->addWidget(table,1); auto* buttons=new QDialogButtonBox(QDialogButtonBox::Close); buttons->button(QDialogButtonBox::Close)->setText("关闭"); layout->addWidget(buttons); connect(buttons,&QDialogButtonBox::rejected,dialog,&QDialog::reject); dialog->show(); const QPointer<QDialog> guard(dialog);
    controller_->inspectNetworkInterfaces([guard,info,table](Result result) { if (!guard) return; if (!result.ok) { info->setText(result.error); return; } info->setText("系统IPv4路由出口（目标 "+result.data.value("route_target").toString()+"）："+result.data.value("route_interface").toString("未知")+"。仅查询路由，不发送请求；TUN开启时这里可能为虚拟网卡，不等同物理出口。"); const auto rows=result.data.value("interfaces").toArray(); table->setRowCount(rows.size()); for (int i=0;i<rows.size();++i) { const auto item=rows[i].toObject(); QStringList addresses; for (const auto& address:item.value("addresses").toArray()) addresses.append(address.toString()); const QStringList cells{item.value("label").toString(),item.value("up").toBool()?QString("已启用"):QString("未启用"),addresses.join("\n")}; for (int col=0;col<cells.size();++col) { auto* cell=new QTableWidgetItem(cells[col]); cell->setToolTip(cells[col]); table->setItem(i,col,cell); } } table->resizeRowsToContents(); });
}
